games=[]
for cat,arr in [('大作',big),('クソゲー',kuso),('ミニゲーム',mini)]:
    for title,mode,desc in arr:
        i=len(games)+1
        cfg={'id':i,'title':f'{i:03d} {title}','desc':desc,'mode':mode,'color':['#67e8f9','#f472b6','#facc15','#86efac','#c084fc'][i%5],'time':45 if cat=='大作' else (20 if cat=='クソゲー' else 12),'target':50 if cat=='大作' else (12 if cat=='クソゲー' else 3),'pairs':8 if cat=='大作' else (4 if cat=='クソゲー' else 2),'count':9 if cat=='大作' else (5 if cat=='クソゲー' else 2),'words':['あぶろっくす','クソゲー','bookmarklet','寿司','ねこ'][i%5]}
        games.append({'no':i,'category':cat,'title':title,'mode':mode,'desc':desc,'config':cfg,'code':line(cfg)})

(ROOT/'games.json').write_text(json.dumps(games,ensure_ascii=False,indent=2),encoding='utf-8')
with (ROOT/'bookmarklets.js').open('w',encoding='utf-8') as f:
    f.write('// Abloxmusic bookmarklet games: each non-empty line is a standalone one-line bookmarklet.\n')
    for g in games: f.write(f"// {g['no']:03d} [{g['category']}] {g['title']}\n{g['code']}\n")

html='''<!doctype html><meta charset="utf-8"><title>Abloxmusic Bookmarklet Arcade 100</title><style>body{margin:0;background:#080b16;color:#eef2ff;font:16px system-ui;padding:32px}h1{color:#67e8f9}main{max-width:1100px;margin:auto}.intro{padding:18px;border:1px solid #334155;border-radius:14px;background:#111827}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.tab,button{background:#172554;color:#e0f2fe;border:1px solid #38bdf8;border-radius:9px;padding:9px 12px;cursor:pointer}.tab.active{background:#0e7490}.card{display:grid;grid-template-columns:64px 1fr auto;gap:16px;align-items:center;padding:13px;margin:8px 0;background:#111827;border:1px solid #1e293b;border-radius:12px}.num{color:#67e8f9;font:700 20px monospace}.meta{color:#94a3b8;font-size:13px}.copy{white-space:nowrap}code{display:none}</style><main><h1>Abloxmusic Bookmarklet Arcade 100</h1><div class=intro>「コピー」してブラウザのブックマークURL欄に貼り付け、任意のページで実行できます。既存のscript.js / cargame.jsは変更していません。</div><div class=tabs><button class="tab active" data-c="すべて">すべて 100</button><button class=tab data-c="大作">大作 30</button><button class=tab data-c="クソゲー">クソゲー 40</button><button class=tab data-c="ミニゲーム">ミニゲーム 30</button></div><section id=list></section></main><script src="games.json"></script><script>const list=document.querySelector('#list'),tabs=document.querySelectorAll('.tab');function render(c='すべて'){list.innerHTML=GAMES.filter(x=>c==='すべて'||x.category===c).map(x=>`<article class=card><div class=num>${String(x.no).padStart(3,'0')}</div><div><b>${x.title}</b><div class=meta>${x.category} / ${x.mode} / ${x.desc}</div></div><button class=copy data-n="${x.no}">1行をコピー</button></article>`).join('');document.querySelectorAll('.copy').forEach(b=>b.onclick=()=>{let x=GAMES.find(y=>y.no==b.dataset.n);navigator.clipboard.writeText(x.code).then(()=>{b.textContent='コピー済み';setTimeout(()=>b.textContent='1行をコピー',1200)})})}tabs.forEach(t=>t.onclick=()=>{tabs.forEach(x=>x.classList.remove('active'));t.classList.add('active');render(t.dataset.c)});render();</script>'''
html=html.replace('<script src="games.json"></script>','<script>const GAMES='+json.dumps(games,ensure_ascii=False,separators=(',',':'))+'</script>')
(ROOT/'index.html').write_text(html,encoding='utf-8')
(ROOT/'README.md').write_text('''# Bookmarklet Arcade 100\n\n`bookmarklets.js` の各コード行は、単独でブラウザのブックマークURLに貼れる `javascript:` bookmarklet です。`index.html` をローカルで開くと、100本をカテゴリ別に絞り込み、ワンクリックでコピーできます。\n\n- 大作: 30本\n- クソゲー: 40本\n- ミニゲーム: 30本\n\nゲームは外部ライブラリ・外部通信なしです。起動中に右上の `×` で閉じられます。既存の `script.js` と `cargame.js` はそのまま残しています。\n''',encoding='utf-8')
